(7000191, 1058173, 97225, '<td valign="top">This is gorgeous!  It just makes me smile and feel happy to look at this portrait. My stand alone top pick. 10. Fave!</td>', 'This is gorgeous!  It just makes me smile and feel happy to look at this portrait. My stand alone top pick. 10. Fave!', '2013-03-14 21:21:20.000000', NULL, 1),
(7000194, 1058097, 97225, '<td valign="top">I love the expression on this little boy''s lovely face.</td>', 'I love the expression on this little boy''s lovely face.', '2013-03-14 21:23:33.000000', NULL, 1),
(7000195, 1057985, 97225, '<td valign="top">Nice lighting, and interesting expression.</td>', 'Nice lighting, and interesting expression.', '2013-03-14 21:24:01.000000', NULL, 1),
(7000354, 1057927, 121949, '<td valign="top">I think that she needed to be closer to the candle I don''t mind the darkness but her face needs to be more the focal point instead of the candle and right now it is very secondary. The weird catch lights in her eyes take away from the mood you are trying to create. I like the reflection much more than I like the main part of the photo. I think in this case it would have been better to have her looking in a different direction, right now her look is leading me away and out of the photo. I think looking more to the side like the reflection or right at camera would have been better. I think this photo is a good idea but is suffering a bit from minimal editing. I think most problems could have been fixed in advanced.</td>', 'I think that she needed to be closer to the candle I don''t mind the darkness but her face needs to be more the focal point instead of the candle and right now it is very secondary. The weird catch lights in her eyes take away from the mood you are trying to create. I like the reflection much more than I like the main part of the photo. I think in this case it would have been better to have her looking in a different direction, right now her look is leading me away and out of the photo. I think looking more to the side like the reflection or right at camera would have been better. I think this photo is a good idea but is suffering a bit from minimal editing. I think most problems could have been fixed in advanced.', '2013-03-14 23:56:38.000000', NULL, 1),
(7000598, 1057419, 135629, '<td valign="top">WOW! that''s a lot of hair! Haha, great shot!</td>', 'WOW! that''s a lot of hair! Haha, great shot!', '2013-03-15 07:30:17.000000', NULL, 1),
(7001003, 1057928, 124982, '<td valign="top">Had potential, but very underexposed. Can''t see any facial features except for the teeth.</td>', 'Had potential, but very underexposed. Can''t see any facial features except for the teeth.', '2013-03-15 18:03:04.000000', NULL, 1),
