(7002200, 1058202, 108580, '<td valign="top">Lovely. I particularly like the unusual non-traditional composition and bleeding light.</td>', 'Lovely. I particularly like the unusual non-traditional composition and bleeding light.', '2013-03-18 05:59:56.000000', NULL, 1),
(7002307, 1058079, 82999, '<td valign="top">One of my top pics.  Well done.</td>', 'One of my top pics.  Well done.', '2013-03-18 11:26:40.000000', NULL, 1),
(7002308, 1058218, 82999, '<td valign="top">Definitely one of the best of the bunch.  Usually the contrast and tonal range in a minimal black and white is pretty flat.  I think the depth of both in this are very good considering the limitations of the challenge.</td>', 'Definitely one of the best of the bunch.  Usually the contrast and tonal range in a minimal black and white is pretty flat.  I think the depth of both in this are very good considering the limitations of the challenge.', '2013-03-18 11:27:34.000000', NULL, 1),
(7002310, 1058173, 82999, '<td valign="top">Very cute.  Very well done.Not big on the catch lights.  A bit distracting and distinct.</td>', 'Very cute.  Very well done.Not big on the catch lights.  A bit distracting and distinct.', '2013-03-18 11:28:28.000000', NULL, 1),
